      "id": "step_1",
      "objective": "Identify Trail Shell Jacket product details",
      "purpose": "Retrieve product_id, category, list price, launch date, and exact naming to anchor messaging in true product attributes.",
      "tool_candidates": ["run_sql"],
      "inputs": {
        "query": "SELECT product_id, product_name, category, list_price, unit_cost, launch_date FROM public.products WHERE product_name ILIKE '%Trail Shell Jacket%';"
