    {
      "id": "step_2",
      "objective": "Analyze customer reviews and feedback themes",
      "purpose": "Analyze rating distribution and extract prominent customer language, praised features/benefits, and critical objections or complaints from deduplicated reviews.",
      "tool_candidates": ["run_sql"],
      "inputs": {
        "query": "SELECT r.rating, r.review_title, r.review_text FROM (SELECT DISTINCT review_id, product_id, rating, review_title, review_text FROM public.reviews) r JOIN public.products p ON r.product_id = p.product_id WHERE p.product_name ILIKE '%Trail Shell Jacket%';"
      },
      "depends_on": [
        {
          "step_id": "step_1",
          "output_key": "product_details",
          "optional": false
