      "output_key": "review_insights",
      "guide_ids": ["KB3", "KB5"],
      "status": "pending",
      "optional": false,
      "skip_if_data_unavailable": false
    },
    {
      "id": "step_3",
      "objective": "Examine return and fulfillment dynamics for the product",
      "purpose": "Check return rates or delivery metrics to see if product returns reinforce any specific objections found in reviews.",
      "tool_candidates": ["run_sql"],
      "inputs": {
        "query": "SELECT o.status, COUNT(DISTINCT o.order_id) AS order_count, SUM(oi.quantity) AS total_units FROM public.orders o JOIN public.order_items oi ON o.order_id = oi.order_id JOIN public.products p ON oi.product_id = p.product_id JOIN public.customers c ON o.customer_id = c.customer_id WHERE p.product_name ILIKE '%Trail Shell Jacket%' AND c.is_internal = false GROUP BY o.status;"
      },
      "depends_on": [
        {
          "step_id": "step_1",
          "output_key": "product_details",
          "optional": false
